from pydantic import Field, BaseModel
from noether.core.schemas.dataset import FieldDimSpec


class AcademicDataSpecs(BaseModel):
    """Defines the complete data specification for a surrogate model"""

    position_dim: int = Field(..., ge=1)
    """Dimension of the input position vectors."""

    input_features: FieldDimSpec
    '''dict of input features and correspondg shapes. If None, a constant feature of shape 1 will be generated by the pipeline'''

    output_targets: FieldDimSpec
    '''dict of output targets'''

    @property
    def model_input_dim(self) -> int:
        if self.input_features is None:
            return 1
        else:
            return self.input_features.total_dim
    
    @property
    def model_output_dim(self) -> int:
        return self.output_targets.total_dim